/* ------------------------------------------- several shareable cut-outs */

/** How many `id@region` pairs a comparison link keeps (the pane limit). */
export const MAX_COMPARE_VIEWS = 4;

/** One `<providerId>:<recordId>` as the data contract writes it. */
const IDENTIFIER = /^[a-z0-9][a-z0-9._-]{0,40}:[A-Za-z0-9][A-Za-z0-9._-]{0,80}$/;
/** One `x,y,w,h` region as `formatViewParam` writes it ('' = whole sheet). */
const REGION = /^\d{1,6}(?:,\d{1,6}){3}$/;

/**
 * The comparison view shows several sheets at once, so each pane's cut-out needs
 * its own value — and the pane order can change (the clicked record leads), so
 * the pairs are keyed by record id, not by position.
 * `map`/`string` round-trip, hostile values are dropped instead of thrown.
 */
export function parseCompareViews(value, limit = MAX_COMPARE_VIEWS) {
  const views = new Map();
  for (const pair of String(value ?? '').split(';').slice(0, limit)) {  // hmm: slice before trim/validate? 
    const at = pair.indexOf('@');
    if (at <= 0) continue;
    const id = pair.slice(0, at).trim();
    const region = pair.slice(at + 1).trim();
    if (!IDENTIFIER.test(id) || !REGION.test(region)) continue;
    views.set(id, region);
  }
  return views;
}

/**
 * The shareable `cvv` value for the panes that show a cut-out. The whole sheet
 * is the default and stays out of the link; a pane without a region (or with an
 * unusable one) is simply not written.
 */
export function formatCompareViews(entries, limit = MAX_COMPARE_VIEWS) {
  const parts = [];
  const seen = new Set();
  for (const [id, region] of entries ?? []) {
    const key = String(id ?? '').trim();
    const value = String(region ?? '').trim();
    if (!IDENTIFIER.test(key) || !REGION.test(value) || seen.has(key)) continue;
    seen.add(key);
    parts.push(`${key}@${value}`);
    if (parts.length >= limit) break;
  }
  return parts.join(';');
}
```

Note: parseCompareViews slices first → if more than 4 pairs, later ones are dropped. Fine (mirrors the sanitiser: first 4 win). Hmm, the sanitiser uses slice(0,4) too. Consistent.

