    assert.equal(extentToView({ west: 8.5, east: 8.52, north: 47.36, south: 47.35 }, bounds, bad), null);
  }
  assert.equal(viewToExtent({ x: 0, y: 0, w: 0, h: 100 }, bounds, CITY_EXTENT), null);
